import{z as B,x as A,o as s,c as p,q as i,j as n,D as t,d as e,s as l,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"incast","description":"","frontmatter":{"title":"incast","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/incast.md","filePath":"cs/incast.md","lastUpdated":1791413859000}'),C={name:"cs/incast.md"};function d(c,a,T,h,u,D){const r=A("Mermaid");return s(),p("div",null,[a[2]||(a[2]=i('<h1 id="incast" tabindex="-1">incast <a class="header-anchor" href="#incast" aria-label="Permalink to &quot;incast&quot;">​</a></h1><div class="epigraph"><p>许多发送方同时打向同一接收方的浅缓冲，瞬时队列溢出；丢的是尾，TCP 超时把好链路当成死。 </p><footer>—— 据 Chen, Braud 等数据中心 TCP incast 研究；Alizadeh 等对 DCTCP 动机整理</footer></div><p><a href="/cs/datacenter-clos">上一课</a> 的多对一仍汇到叶子出口。<a href="/cs/output-queue-hol">输出排队</a> 已说热点。缺口是<strong>应用同步扇入</strong>：MapReduce shuffle、存储多块并发读。本课不把 DCTCP 标记写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RTO 最小在毫秒，数据中心 RTT 在微秒。incast：N 个流的初始窗口同时到达，叶子出端口缓冲只有几十到上百 KB，丢包 → 超时 → 吞吐塌成「好网很慢」。不是 \\(C\\) 不够，是瞬态超订。巨帧让一包占更多缓冲。PFC 可避免丢，但暂停波及 Clos 其它流。</p><p><span class="marginnote">数字实例：数据中心 RTT 约 50–100 微秒，TCP RTO 下限却在百毫秒量级——一次超时够正常往返几千次。32 个发送方各带 64 KB 初始窗口同时涌入，约 2 MB 要在几十微秒内挤过一个几百 KB 的出端口缓冲，尾丢几乎必然发生。</span></p><p>不要把 incast 写成广域拥塞崩溃：时间尺度与扇入结构不同。</p><p><span class="marginnote">文献用 barrier 同步流量复现。本课不给攻击。对策方向：更深缓冲（加重 bufferbloat）、减小 IW、AQM、DCTCP、应用限流。</span></p><h3 id="同步扇入打浅缓冲" tabindex="-1">同步扇入打浅缓冲 <a class="header-anchor" href="#同步扇入打浅缓冲" aria-label="Permalink to &quot;同步扇入打浅缓冲&quot;">​</a></h3><p>不是平均 \\(C\\) 不够。短流凑不够 dupACK 只剩 RTO。ECMP 不拆同一出口。加大缓冲会转向膨胀。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：N 发送 → 一出口浅队列 → 丢 → RTO。对照 HOL：结构内部也可丢；incast 强调应用同步。ECMP 帮不上：目的是同一叶子口。</p><p><span class="marginnote">直觉类比：incast 像散场时一千人同时挤向一个旋转门——不是门不够宽（平均带宽够），而是所有人同一秒涌到。被挤掉票的人（丢包）要等「下一个开放时段」（RTO）才能重进，可门后明明早就没人排队了。</span></p>',13)),(s(),n(o,null,{default:t(()=>[l(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22N%20%E4%B8%AA%E5%8F%91%E9%80%81%E6%96%B9%22%5D%20--%3E%20Q%5B%22%E6%B5%85%E5%87%BA%E9%98%9F%E5%88%97%22%5D%0A%20%20Q%20--%3E%20DROP%5B%22%E5%B0%BE%E4%B8%A2%22%5D%0A%20%20DROP%20--%3E%20RTO%5B%22%E8%B6%85%E6%97%B6%22%5D%0A%20%20RTO%20--%3E%20THR%5B%22%E5%90%9E%E5%90%90%E5%A1%8C%E9%99%B7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("Clos 过订购比放大汇聚。RoCE 后课更怕丢，故无损。TCP 快速重传要三个 dupACK，短流可能根本凑不够——只剩超时。这把"),E("a",{href:"/cs/tcp-rto"},"RTO"),e(" 课的下限暴露成数据中心 bug。")],-1)),(s(),n(o,null,{default:t(()=>[l(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E6%9F%90%E6%B5%81%E4%B8%A2%E4%BA%86%E4%B8%80%E4%B8%AA%E5%8C%85%22%5D%20--%3E%20A%5B%22%E7%AC%AC%201%20%E4%B8%AA%E5%90%8E%E7%BB%AD%E5%8C%85%E5%88%B0%E8%BE%BE%EF%BC%9A1%20%E4%B8%AA%20dupACK%22%5D%0A%20%20A%20--%3E%20B%5B%22%E7%AC%AC%202%20%E4%B8%AA%E5%88%B0%E8%BE%BE%EF%BC%9A2%20%E4%B8%AA%20dupACK%22%5D%0A%20%20B%20--%3E%20C%5B%22%E7%AC%AC%203%20%E4%B8%AA%E5%88%B0%E8%BE%BE%EF%BC%9A%E8%A7%A6%E5%8F%91%E5%BF%AB%E9%80%9F%E9%87%8D%E4%BC%A0%22%5D%0A%20%20C%20--%3E%20OK%5B%22%E5%BE%AE%E7%A7%92%E5%86%85%E6%81%A2%E5%A4%8D%EF%BC%8C%E6%97%A0%E9%9C%80%E8%B6%85%E6%97%B6%22%5D%0A%20%20B%20-.-%3E%7C%22%E7%9F%AD%E6%B5%81%E5%B7%B2%E5%8F%91%E5%AE%8C%EF%BC%8C%E5%87%91%E4%B8%8D%E9%BD%90%203%20%E4%B8%AA%22%7C%20T%5B%22%E5%8F%AA%E8%83%BD%E5%B9%B2%E7%AD%89%20RTO%EF%BC%9A%E7%99%BE%E6%AF%AB%E7%A7%92%E7%BA%A7%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">PFC（优先级流控暂停）的代价直觉：它不丢包，而是让上游「全体闭嘴」；在 Clos 里这条暂停会一站站向回传染，把毫不相干流量的队列也一起憋住——堵换了个地方，还可能憋出死锁。所以「无损网络」不是免费的。</span></p><p>应用层：限制并发、请求错开，是端到端对策，符合 Saltzer。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入每种存储协议的扇入参数。DCTCP 是下一课。后课默认：incast = 同步多对一打浅缓冲。</p><p>加大缓冲能盖 incast，会把延迟交给后课缓冲膨胀。</p><p>下一课<a href="/cs/dctcp">DCTCP</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>同步扇入溢出浅队列，RTO 主导。</li><li>ECMP 不拆同一出口。</li><li>对策在 AQM/DCTCP/应用限流，不只加带宽。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：数据中心 incast 文献；DCTCP 动机。</li></ul>',8))])}const P=B(C,[["render",d]]);export{f as __pageData,P as default};
